#include <vector>
#include <algorithm>
using namespace std;

int remove_dups(vector<int>& a) {
    if (a.empty()) return 0;
    int k = 1;                                   // write pointer
    for (size_t i = 1; i < a.size(); i++)        // read pointer
        if (a[i] != a[k - 1]) a[k++] = a[i];
    return k;                                    // optionally a.resize(k)
}

// Follow-up: keep at most two copies of each value (LeetCode 80)
int remove_dups2(vector<int>& a) {
    int k = 0;
    for (int x : a)
        if (k < 2 || x != a[k - 2]) a[k++] = x;
    return k;
}

