**Key idea:** `operator[]` on an `unordered_map<int,int>` default-constructs a missing count to 0, so `m[x]++` is the whole counting step. For top-k, copy the (value, count) pairs to a vector and `partial_sort` only the first k positions.

| step | content |
| --- | --- |
| input | 1 1 1 2 2 3 |
| freq map | {1: 3, 2: 2, 3: 1} |
| pairs vector | (1,3) (2,2) (3,1) in hash order |
| partial_sort k=2 by count desc | **(1,3) (2,2)** (3,1) |
| resize(k) | (1,3) (2,2) |

### Code
```cpp
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <utility>
using namespace std;

unordered_map<int, int> freq(const vector<int>& a) {
    unordered_map<int, int> cnt;
    for (int x : a) cnt[x]++;                    // missing key starts at 0
    return cnt;
}

vector<pair<int, int>> top_k(const vector<int>& a, int k) {
    auto cnt = freq(a);
    vector<pair<int, int>> v(cnt.begin(), cnt.end());
    k = min<int>(k, (int)v.size());
    partial_sort(v.begin(), v.begin() + k, v.end(),
                 [](const auto& l, const auto& r) {
                     if (l.second != r.second) return l.second > r.second;
                     return l.first < r.first;   // deterministic tie-break
                 });
    v.resize(k);
    return v;
}
```

