#include <string>
#include <utility>
using namespace std;

void reverse_str(string& s) {
    int i = 0, j = (int)s.size() - 1;     // int: "" gives j = -1, loop skipped
    while (i < j) swap(s[i++], s[j--]);
}

// C-string version
void reverse_c(char* s) {
    if (s == nullptr || *s == '\0') return;   // empty: avoid e pointing before s
    char* e = s;
    while (*(e + 1)) e++;                     // e -> last char before '\0'
    while (s < e) {
        char t = *s;
        *s++ = *e;
        *e-- = t;
    }
}
// STL: std::reverse(s.begin(), s.end());
