#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

bool is_anagram(const string& a, const string& b) {
    if (a.size() != b.size()) return false;
    int cnt[26] = {0};
    for (char c : a) cnt[c - 'a']++;
    for (char c : b) if (--cnt[c - 'a'] < 0) return false;
    return true;
}

// Follow-up: group anagrams (LeetCode 49)
vector<vector<string>> group_anagrams(const vector<string>& words) {
    unordered_map<string, vector<string>> groups;
    for (const auto& w : words) {
        string key = w;
        sort(key.begin(), key.end());            // "eat" -> "aet"
        groups[key].push_back(w);
    }
    vector<vector<string>> out;
    for (auto& [k, g] : groups) out.push_back(move(g));
    return out;
}
