#include <fstream>
#include <sstream>
#include <iostream>
#include <string>
#include <unordered_map>
#include <unordered_set>
using namespace std;

unordered_map<string, int> count_severity(const string& path) {
    static const unordered_set<string> SEV =
        {"UVM_INFO", "UVM_WARNING", "UVM_ERROR", "UVM_FATAL"};
    unordered_map<string, int> cnt;
    ifstream f(path);
    if (!f) { cerr << "cannot open " << path << "\n"; return cnt; }

    string line;
    while (getline(f, line)) {                 // one line at a time
        istringstream ss(line);
        string sev, next;
        ss >> sev >> next;
        if (SEV.count(sev) && next != ":")     // skip "UVM_ERROR :    1"
            cnt[sev]++;
    }
    return cnt;                                // ifstream closes itself (RAII)
}

int main(int argc, char** argv) {
    auto c = count_severity(argc > 1 ? argv[1] : "sim.log");
    for (const char* s : {"UVM_INFO", "UVM_WARNING", "UVM_ERROR", "UVM_FATAL"})
        cout << s << "=" << c[s] << " ";
    cout << "\n";
}
