**Key idea:** a FIFO is a queue with a capacity. `std::deque` gives O(1) at both ends; a **ring buffer** mirrors the RTL: a write pointer, a read pointer that wrap around, and a count (RTL uses one extra pointer bit instead) to tell full from empty.

Ring buffer trace, depth 2:

| op | rd | wr | count | buf | result |
| --- | --- | --- | --- | --- | --- |
| init | 0 | 0 | 0 | [-, -] | |
| push 10 | 0 | 1 | 1 | [10, -] | ok |
| push 20 | 0 | 0 | 2 | [10, 20] | ok (wr wrapped) |
| push 30 | 0 | 0 | 2 | [10, 20] | **false: full** |
| pop | 1 | 0 | 1 | [10, 20] | 10 |
| push 30 | 1 | 1 | 2 | [30, 20] | ok |
| pop | 0 | 1 | 1 | [30, 20] | 20 |
| pop | 1 | 1 | 0 | [30, 20] | 30, now empty (rd == wr) |

Note `rd == wr` both when full and when empty: that is why the count (or extra MSB) is needed.

### Code
```cpp
#include <deque>
#include <vector>
#include <stdexcept>
using namespace std;

// 1. deque-based, templated
template <typename T>
class Fifo {
public:
    explicit Fifo(size_t depth) : depth_(depth) {}
    void push(const T& x) {
        if (full()) throw overflow_error("push when full");
        q_.push_back(x);
    }
    T pop() {
        if (empty()) throw underflow_error("pop when empty");
        T x = q_.front();              // pop_front() returns void
        q_.pop_front();
        return x;
    }
    bool   full()  const { return q_.size() == depth_; }
    bool   empty() const { return q_.empty(); }
    size_t size()  const { return q_.size(); }
private:
    size_t   depth_;
    deque<T> q_;
};

// 2. circular buffer, mirrors RTL pointers
class RingFifo {
    vector<int> buf;
    size_t rd = 0, wr = 0, count = 0;
public:
    explicit RingFifo(size_t depth) : buf(depth) {}
    bool push(int x) {
        if (count == buf.size()) return false;
        buf[wr] = x; wr = (wr + 1) % buf.size(); count++;
        return true;
    }
    bool pop(int& x) {
        if (count == 0) return false;
        x = buf[rd]; rd = (rd + 1) % buf.size(); count--;
        return true;
    }
    bool full()  const { return count == buf.size(); }
    bool empty() const { return count == 0; }
};
```

