#include <cstdio>

struct Node { int val; Node* next; };

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt  = head->next;   // 1. save the rest
        head->next = prev;         // 2. flip the pointer
        prev = head;               // 3. advance prev
        head = nxt;                // 4. advance head
    }
    return prev;                   // new head
}

// Recursive version (O(n) stack depth)
Node* reverse_rec(Node* h) {
    if (!h || !h->next) return h;
    Node* new_head = reverse_rec(h->next);
    h->next->next = h;
    h->next = nullptr;
    return new_head;
}

int main() {
    Node c{3, nullptr}, b{2, &c}, a{1, &b};
    for (Node* p = reverse_list(&a); p; p = p->next) printf("%d ", p->val);   // 3 2 1
}
